def getAverageStanding(d, records):
    from collections import defaultdict
    from math import gcd
    races = defaultdict(list)
    for race_id, pid, ptime in records:
        races[race_id].append((pid, ptime))
    p_sum = [0] * d
    p_cnt = [0] * d
    for race_id, lst in races.items():
        lst.sort(key=lambda x: (x[1], x[0]))
        for rank, (pid, _) in enumerate(lst, 1):
            p_sum[pid] += rank
            p_cnt[pid] += 1
    res = []
    for i in range(d):
        if p_cnt[i] == 0:
            res.append([-1, -1])
        else:
            g = gcd(p_sum[i], p_cnt[i])
            res.append([p_sum[i] // g, p_cnt[i] // g])
    return res

class Solution {
    long gcd(long a, long b) { return b == 0 ? a : gcd(b, a % b); }
    public int[][] getAverageStanding(int d, int[][] records) {
        java.util.HashMap<Integer, java.util.List<int[]>> races = new java.util.HashMap<>();
        for (int[] r : records) races.computeIfAbsent(r[0], k -> new java.util.ArrayList<>()).add(new int[]{r[1], r[2]});
        long[] sum = new long[d];
        int[] cnt = new int[d];
        for (var lst : races.values()) {
            lst.sort((a, b) -> a[1] != b[1] ? Integer.compare(a[1], b[1]) : Integer.compare(a[0], b[0]));
            for (int i = 0; i < lst.size(); i++) {
                int pid = lst.get(i)[0];
                sum[pid] += i + 1;
                cnt[pid]++;
            }
        }
        int[][] res = new int[d][2];
        for (int i = 0; i < d; i++) {
            if (cnt[i] == 0) { res[i][0] = -1; res[i][1] = -1; }
            else { long g = gcd(sum[i], cnt[i]); res[i][0] = (int)(sum[i] / g); res[i][1] = (int)(cnt[i] / g); }
        }
        return res;
    }
}

class Solution {
public:
    long long gcd(long long a, long long b) { return b == 0 ? a : gcd(b, a % b); }
    vector<vector<int>> getAverageStanding(int d, vector<vector<int>>& records) {
        unordered_map<int, vector<pair<int,int>>> races;
        for (auto& r : records) races[r[0]].push_back({r[1], r[2]});
        vector<long long> sum(d, 0);
        vector<int> cnt(d, 0);
        for (auto& [k, lst] : races) {
            sort(lst.begin(), lst.end(), [](auto& a, auto& b){ return a.second != b.second ? a.second < b.second : a.first < b.first; });
            for (int i = 0; i < (int)lst.size(); i++) {
                int pid = lst[i].first;
                sum[pid] += i + 1;
                cnt[pid]++;
            }
        }
        vector<vector<int>> res(d, vector<int>(2));
        for (int i = 0; i < d; i++) {
            if (cnt[i] == 0) { res[i] = {-1, -1}; }
            else { long long g = gcd(sum[i], cnt[i]); res[i] = {(int)(sum[i] / g), (int)(cnt[i] / g)}; }
        }
        return res;
    }
};
